  function findPath(start,goal){const q=[start],prev=new Map([[start,null]]);for(let i=0;i<q.length;i++){const here=q[i];if(here===goal)break;const [x,y]=xy(here);for(const [nx,ny] of [[x,y-1],[x-1,y],[x,y+1],[x+1,y]]){const next=key(nx,ny);if(nx<0||ny<0||nx>=W||ny>=H||water.has(next)||prev.has(next))continue;prev.set(next,here);q.push(next)}}if(!prev.has(goal))return null;const path=[];for(let at=goal;at&&at!==start;at=prev.get(at))path.unshift(at);return path}
