    if(!raidHere&&(typ==='path'||typ==='wild')&&k===state.pos&&!state.travel&&!state.inside){const buy=document.createElement('button');buy.textContent=`この土地を購入 · ${PLOT_PRICE.toLocaleString()}pt`;buy.disabled=state.points<PLOT_PRICE;buy.addEventListener('click',()=>buyPlotAt(k));wrap.appendChild(buy)}
    if(k===state.home&&state.pos===state.home&&!state.travel&&!state.inside){const b=document.createElement('button');b.textContent='家の中を見る';b.addEventListener('click',enterHome);wrap.appendChild(b)}
    if(typ==='own'&&!state.inside){const b=document.createElement('button');b.textContent=`🛡 ${xLabel(k)}の防衛を設定`;b.addEventListener('click',()=>{shopTab='defense';renderShop();$('shopDialog').showModal()});wrap.appendChild(b)}
