  function clickRoomSlot(slot){state.houseSlot=slot;const existing=state.decor.find(d=>d.slot===slot);if(state.pendingItem){if(existing){log('その床にはすでに家具が置いてある。');renderHouse();return}const i=state.inventory.findIndex(entry=>entry.uid===state.pendingItem);if(i>=0){const piece=state.inventory.splice(i,1)[0];piece.slot=slot;state.decor.push(piece);log(`${itemFor(piece.id)?.name||'家具'}を家に飾った。`)}state.pendingItem=null}else if(existing){state.pendingMove=existing.uid;state.pendingItem=null;$('houseMessage').textContent='移動先の空いている床を選んでください。'}else if(state.pendingMove){const piece=state.decor.find(d=>d.uid===state.pendingMove);if(piece){piece.slot=slot;log(`${itemFor(piece.id)?.name||'家具'}を移動した。`)}state.pendingMove=null}else $('houseMessage').textContent='空いている床です。家具を選ぶとここに置けます。';render();save()}
  function enterHome(){if(state.pos!==state.home||state.travel)return;state.inside=!state.inside;state.pendingItem=null;state.pendingMove=null;if(state.inside){log('はじまりの家に入った。家具を飾ってみよう。')}else log('家を出て、原っぱへ戻った。');render();save()}
  function buyPlotAt(k){if(k!==state.pos||state.travel||state.inside||state.points<PLOT_PRICE||has(k)||ownedElse(k)||water.has(k))return;state.points-=PLOT_PRICE;state.lands.push(k);state.past.push(k);state.ownedSince[k]=Date.now();selected=k;log(`${xLabel(k)}を${PLOT_PRICE.toLocaleString()}ptで購入した。ここから収入が生まれる。`);render();save()}
  function buyItem(item,price){if(state.points<price)return false;if(item.kind==='gear'&&item.role==='defense'){const land=selected;if(!has(land))return false;const count=itemCount(item.id,land);if(count>=3)return false;state.points-=price;state.landGear[land]=state.landGear[land]||{};state.landGear[land][item.id]={count:count+1,level:gearLevel(item.id,land)};log(`${xLabel(land)}に${item.name}を設置した。防衛装置 ${count+1}/3。`)}else if(item.kind==='wall'){const level=Number(state.wallStyles[item.id])||0;if(level>=3)return false;state.points-=price;state.wallStyles[item.id]=level+1;state.wallStyle=item.id;log(`${item.name}を張った。壁紙 Lv.${level+1}になった。`)}else if(item.kind==='gear'){if(itemCount(item.id)>=3)return false;state.points-=price;state.gear[item.id]={count:itemCount(item.id)+1,level:gearLevel(item.id)};log(`${item.name}を設置した。装備数 ${itemCount(item.id)}/3。`)}else{if(itemCount(item.id)>=3)return false;state.points-=price;const piece=makeInventoryItem(item.id);state.inventory.push(piece);if(state.pos===state.home){state.pendingItem=piece.uid;state.inside=true}log(`${item.name}を買った。家に置いて育てよう。`)}render();save();return true}
  function upgradeItem(item){if(item.kind==='gear'&&item.role==='defense'){const land=selected,gear=state.landGear[land]?.[item.id];if(!has(land)||!gear||gear.count<=0)return;const level=gearLevel(item.id,land),price=upgradePrice(item,level);if(state.points<price)return;state.points-=price;gear.level=level+1;log(`${xLabel(land)}の${item.name}を強化した。Lv.${gear.level}！`)}else if(item.kind==='wall'){const level=Number(state.wallStyles[item.id])||0;if(level<=0||level>=3)return;const price=upgradePrice(item,level);if(state.points<price)return;state.points-=price;state.wallStyles[item.id]=level+1;state.wallStyle=item.id;log(`${item.name}を強化した。壁紙 Lv.${level+1}！`)}else if(item.kind==='gear'){const gear=state.gear[item.id];if(!gear||gear.count<=0)return;const level=gearLevel(item.id),price=upgradePrice(item,level);if(state.points<price)return;state.points-=price;gear.level=level+1;log(`${item.name}を強化した。Lv.${gear.level}！`)}else{const owned=[...state.inventory,...state.decor].filter(piece=>piece.id===item.id).sort((a,b)=>(a.lvl||0)-(b.lvl||0));const piece=owned[0];if(!piece)return;const level=Number(piece.lvl)||0,price=upgradePrice(item,level);if(state.points<price)return;state.points-=price;piece.lvl=level+1;log(`${item.name}を強化した。Lv.${piece.lvl}！`)}render();save()}
  function buySet(set){const contents=set.ids.map(itemFor),canBuy=contents.every(item=>itemCount(item.id)<3);const price=Math.ceil(contents.reduce((sum,item)=>sum+item.cost,0)*.76);if(!canBuy||state.points<price)return;state.points-=price;for(const item of contents){if(item.kind==='wall'){state.wallStyles[item.id]=(Number(state.wallStyles[item.id])||0)+1;state.wallStyle=item.id}else state.inventory.push(makeInventoryItem(item.id))}log(`${set.name}を購入！3つの品を手に入れた。`);render();save()}
  function productCard(item,container,limited=null){const card=document.createElement('article');card.className='shop-item';const landDefense=item.kind==='gear'&&item.role==='defense',land=landDefense&&has(selected)?selected:null,count=landDefense?(land?itemCount(item.id,land):0):itemCount(item.id),owned=item.kind==='wall'?count:item.kind==='gear'?count:[...state.inventory,...state.decor].filter(piece=>piece.id===item.id),lowest=landDefense?(land?gearLevel(item.id,land):0):item.kind==='wall'?count:item.kind==='gear'?gearLevel(item.id):(owned.length?Math.min(...owned.map(piece=>Number(piece.lvl)||0)):0),price=item.cost*(1+count*.25),upgrade=landDefense?count>0:owned.length||item.kind==='wall'&&count>0,upgradeCost=upgradePrice(item,lowest);card.innerHTML=`<span class="emoji">${item.icon}</span><strong>${item.name}</strong><small>${item.desc}<br>${landDefense?(land?`設置先 ${xLabel(land)} · ${count}/3 · 防衛力 +${Math.round(landDefensePower(land)*100)}%`:'先に自分の土地を選択してください'):`所持 ${count}/3${item.kind==='wall'?` · Lv.${count}`:upgrade?` · 強化対象 Lv.${lowest}`:''}`}</small>`;const buy=document.createElement('button');buy.textContent=limited?`${limited.price} pt · 限定品購入`:item.kind==='wall'?count>=3?'最大強化':`${Math.ceil(price)} pt · 壁紙を強化 (${count}/3)`:count>=3?'この土地の設置上限':`${Math.ceil(price)} pt · ${landDefense?'この土地に設置':'購入'} (${count}/3)`;buy.disabled=limited?(limited.sold||count>=3||state.points<limited.price):(count>=3||state.points<price||landDefense&&!land);buy.addEventListener('click',()=>{if(limited){if(limited.sold)return;if(buyItem(item,limited.price)){limited.sold=true;render();save()}}else buyItem(item,Math.ceil(price))});card.appendChild(buy);const up=document.createElement('button');up.className='upgrade-button';up.textContent=item.kind==='wall'?count===0?'先に壁紙を購入':count>=3?'強化上限':`${upgradeCost} pt · 壁紙強化`:`${upgradeCost} pt · ${landDefense?'この土地を強化':'強化'}`;up.disabled=!upgrade||item.kind==='wall'&&count>=3||state.points<upgradeCost||landDefense&&!land;up.addEventListener('click',()=>{if(limited){if(limited.sold)return;if(state.points<upgradeCost)return;upgradeItem(item);limited.sold=true;render();save()}else upgradeItem(item)});card.appendChild(up);container.appendChild(card)}
  function renderShop(){const setsBox=$('shopSets'),box=$('shopItems'),scrollTop=box.scrollTop;setsBox.innerHTML='';box.innerHTML='';setsBox.classList.toggle('hidden',shopTab!=='decor');document.querySelectorAll('[data-shop-tab]').forEach(button=>{const active=button.dataset.shopTab===shopTab;button.classList.toggle('active',active);button.setAttribute('aria-selected',String(active))});const title=$('shopCatalogTitle'),note=$('shopCatalogNote');title.textContent=shopTab==='decor'?'飾り・ポイントアップ':'防衛道具';note.textContent=shopTab==='decor'?'家具や壁紙を家に飾ると、土地から得るポイントが増えます。3点セットもここから。':`防衛装置は選択中の自分の土地に設置されます。設置先：${has(selected)?xLabel(selected):'マップで自分の土地を選んでください'}`;if(shopTab==='decor')for(const set of sets){const contents=set.ids.map(itemFor),price=Math.ceil(contents.reduce((sum,item)=>sum+item.cost,0)*.76),canBuy=contents.every(item=>itemCount(item.id)<3),card=document.createElement('article');card.className='bundle-card';card.innerHTML=`<span class="bundle-icon">${set.icon}</span><strong>${set.name}</strong><small>${contents.map(item=>item.name).join(' · ')}</small>`;const b=document.createElement('button');b.textContent=`${price.toLocaleString()} pt · 3点セット購入`;b.disabled=!canBuy||state.points<price;b.addEventListener('click',()=>buySet(set));card.appendChild(b);setsBox.appendChild(card)}const categoryItems=items.filter(item=>shopTab==='decor'?item.kind!=='gear':item.kind==='gear'&&item.role==='defense');let group='';for(const item of categoryItems){if(group!==item.group){group=item.group;const header=document.createElement('h3');header.className='catalog-group';header.textContent=group;box.appendChild(header)}productCard(item,box)}box.scrollTop=scrollTop;
  }
  function renderLimitedShop(){const panel=$('limitedShopPanel'),shop=state.limitedShop,open=!!(shop&&state.limitedOpen&&state.pos===shop.key&&!state.inside&&shop.closesAt>Date.now());panel.classList.toggle('hidden',!open);if(!open)return;$('limitedShopTimer').textContent=`閉店まで ${Math.max(0,Math.ceil((shop.closesAt-Date.now())/1000))}秒`;$('limitedShopOffers').innerHTML='';for(const offer of shop.stock){const item=itemFor(offer.id);if(!item)continue;const tag=document.createElement('span');tag.className='limited-discount';tag.textContent='本日限り';const card=document.createElement('article');card.className='limited-offer';card.append(tag);const host=document.createElement('div');productCard(item,host,offer);card.append(host);$('limitedShopOffers').appendChild(card)}}
  function raidPlayerDps(){const attack=items.filter(i=>i.kind==='gear'&&i.role==='attack').reduce((n,i)=>n+itemCount(i.id)*(.04+gearLevel(i.id)*.015)*(i.id==='war-banner'?1.4:1),0);return 3+ownedCount()*.45+attack*8}
  function startRaid(now){const site=findVacantLand();if(!site){state.raid.nextAt=now+30000;return}state.raid={active:true,boss:'古代森の守り手',key:site,hp:RAID_BOSS_HP,maxHp:RAID_BOSS_HP,startedAt:now,endsAt:now+RAID_DURATION_MS,lastTick:now,nextAt:now+RAID_INTERVAL_MS,playerJoined:false,playerDamage:0,allies:[],reward:0,defeated:false};sendComputersToRaid(state.raid,now);log(`共同レイドを${xLabel(site)}で発見！現地へ向かおう。`)}
  function finishRaid(now){const raid=state.raid,total=raid.playerDamage+raid.allies.reduce((sum,a)=>sum+a.damage,0),progress=(raid.maxHp-raid.hp)/raid.maxHp;raid.defeated=raid.hp<=0;raid.active=false;raid.endedAt=now;raid.reward=raid.playerDamage>0&&total>0?Math.floor(RAID_REWARD_POOL*progress*raid.playerDamage/total):0;for(const bot of state.computers)if(bot.raidTrip){bot.position=bot.raidTrip.origin;delete bot.raidTrip}if(raid.reward){state.points+=raid.reward;log(`レイド終了！貢献 ${Math.floor(raid.playerDamage)} ダメージ、報酬 ${raid.reward.toLocaleString()}pt。`)}else log(`レイドは${raid.defeated?'討伐成功':'時間切れ'}。今回は報酬なし。`);if(!raid.defeated&&raid.hp>0)raid.remainingHp=Math.ceil(raid.hp)}
  function updateRaid(now){const raid=state.raid;if(!raid.active){if(now>=raid.nextAt){startRaid(now);joinRaidAtSite()}return}joinRaidAtSite();const end=Math.min(now,raid.endsAt),elapsed=Math.max(0,(end-(Number(raid.lastTick)||raid.startedAt))/1000);if(elapsed>0){const onSite=state.pos===raid.key&&!state.travel&&!state.inside,participating=raid.playerJoined&&onSite&&state.morale>0;if(participating)state.morale=Math.max(0,state.morale-elapsed*RAID_MORALE_DRAIN_PER_SECOND);const playerDps=participating?raidPlayerDps():0,arrived=raid.allies.filter(a=>state.computers.some(bot=>bot.id===a.id&&bot.raidTrip?.arrived)),allyDps=arrived.reduce((sum,a)=>sum+a.dps,0),totalDps=playerDps+allyDps,damage=Math.min(raid.hp,totalDps*elapsed);if(totalDps>0){raid.playerDamage+=damage*playerDps/totalDps;for(const ally of arrived)ally.damage+=damage*ally.dps/totalDps;raid.hp=Math.max(0,raid.hp-damage)}raid.lastTick=end}if(raid.hp<=0||now>=raid.endsAt)finishRaid(now)}
  function renderRaid(){joinRaidAtSite();const raid=state.raid,go=$('raidGoBtn'),panel=$('raidPanel'),detail=$('raidDetails'),active=!!raid.active,onSite=active&&state.pos===raid.key&&!state.travel&&!state.inside;panel.classList.toggle('hidden',!active);detail.classList.toggle('hidden',!onSite);go.classList.toggle('hidden',!active||onSite);$('raidStatus').textContent='レイド開催中';go.textContent='レイドに向かう';go.disabled=!!state.travel;if(!onSite)return;$('raidBossName').textContent=raid.boss;const remain=Math.max(0,raid.hp/raid.maxHp*100),progress=100-remain,total=raid.playerDamage+raid.allies.reduce((sum,a)=>sum+a.damage,0),share=total>0?raid.playerDamage/total*100:0;$('raidHp').textContent=`HP ${Math.ceil(raid.hp)} / ${raid.maxHp}（残り${Math.ceil(remain)}%）`;$('raidBar').style.width=`${remain}%`;$('raidProgress').textContent=`削り ${Math.floor(progress)}%`;$('raidContribution').textContent=`あなたの貢献 ${Math.floor(raid.playerDamage)}ダメージ（${Math.floor(share)}%）`;$('raidLocation').textContent=`発見地点：${xLabel(raid.key)} · 現地参加中`;$('raidTeam').textContent=raid.allies.map(a=>{const bot=state.computers.find(b=>b.id===a.id);return `${a.name} ${bot?.raidTrip?.arrived?'現地で攻撃中':'現地へ移動中'}`}).join(' · ')||'あなたが先陣を切っています';$('raidCostNote').textContent=`レイド参加中は気力を毎秒${RAID_MORALE_DRAIN_PER_SECOND.toFixed(2)}消費します。`}

  function updateLimitedShop(now){if(state.limitedShop&&now>=state.limitedShop.closesAt){state.limitedShop=null;state.limitedOpen=false;log('領地の限定ショップが閉店した。次の出店を待とう。')}if(!state.limitedShop&&now>=state.nextShopAt&&state.lands.length){const vacant=Object.keys(cellData).filter(k=>!water.has(k)&&!has(k)&&!ownedElse(k));if(!vacant.length){state.nextShopAt=now+30000;return}const key=vacant[Math.floor(Math.random()*vacant.length)],stock=items.filter(item=>item.kind!=='gear').sort(()=>Math.random()-.5).slice(0,3).map(item=>({id:item.id,price:Math.ceil(item.cost*(.68+Math.random()*.16)),sold:false}));state.limitedShop={key,closesAt:now+120000,stock};state.limitedOpen=state.pos===key&&!state.travel&&!state.inside;state.nextShopAt=now+150000+Math.random()*240000;log(`${xLabel(key)}に限定ショップが開店！閉店まであと2分。`)} }
  function tick(){const now=Date.now();settlePoints(now);updateLimitedShop(now);updateRaid(now);tickTravel(now);if(state.occupy){drainOccupationMorale(now);if(state.occupy.progress>=state.occupy.required)finishOccupation()}tickComputers(now);save();render()}
  function render(){drawMap();renderHouse();actionButtons();renderShop();renderLimitedShop();renderRaid();$('worldMapView').classList.toggle('hidden',state.inside);$('houseView').classList.toggle('hidden',!state.inside);$('homeBtn').textContent=state.inside?'🌲 外へ出る':'🏠 家に入る';$('homeBtn').disabled=state.pos!==state.home||!!state.travel;$('points').textContent=Math.floor(state.points).toLocaleString();$('income').textContent=`${currentPointRate().toFixed(1)} pt / 分`;$('bonus').textContent=`+${Math.min(500,placedBonus())}%`;$('moraleValue').textContent=`${state.morale.toFixed(2)} / ${MORALE_MAX}`;$('moraleBar').style.width=`${Math.max(0,state.morale)/MORALE_MAX*100}%`;$('playerName').textContent=state.name||'冒険者';$('tileCount').textContent=ownedCount();$('playerCount').textContent=1+state.computers.length;$('locationLabel').textContent=state.inside?'はじまりの家の中':state.travel?`${xLabel(state.pos)}を移動中`:state.pos===state.home?'はじまりの家':xLabel(state.pos);const occ=state.occupy;$('occupation').classList.toggle('hidden',!occ);if(occ){$('targetPanel').open=true;const left=Math.max(0,occ.required-((Date.now()-occ.startedAt)/1000));$('occLabel').textContent=occ.type==='wild'?'未開拓地を開拓中…':occ.type==='reclaim'?'領地を奪還中…':'敵の領地を占領中…';$('occDuration').textContent=`所要 ${occ.required}秒`;$('occFormula').textContent=Number.isFinite(occ.base)&&Number.isFinite(occ.attack)&&Number.isFinite(occ.guard)&&Number.isFinite(occ.fortification)?`基礎${occ.base}秒 × 現地防衛${occ.guard} × 土地防衛${(1+occ.fortification).toFixed(2)} ÷ 攻撃${(1+occ.attack).toFixed(2)} = ${occ.required}秒`:'占領開始時の計算内訳は保存されていません';$('occRounding').textContent='端数切り上げ。敵地は最低20秒、奪還は最低8秒。';$('occTime').textContent=`残り${Math.ceil(left)}秒`;$('occBar').style.width=`${Math.min(100,(Date.now()-occ.startedAt)/1000/occ.required*100)}%`}$('interruptBtn').onclick=()=>{cancelOccupation();render();save()};
    const t=state.travel;if(t){const elapsed=Math.max(0,Date.now()-t.startedAt),pct=Math.min(100,elapsed/(t.path.length*t.stepMs)*100),remaining=Math.max(0,Math.ceil((t.path.length*t.stepMs-elapsed)/1000));$('travelLabel').textContent=`${xLabel(t.goal)}へ向かっています · あと${remaining}秒`;$('travelBar').style.width=`${pct}%`;$('travelTrack').classList.add('moving')}else{$('travelLabel').textContent=occ?'占領ゲージが進行中':state.inside?'家具を配置できます':'行き先を選んでね';$('travelBar').style.width='0%';$('travelTrack').classList.remove('moving')}
    $('latestLog').textContent=state.log[0]||'記録を見る';$('eventLog').innerHTML=state.log.map(x=>`<li><time>✦</time>${escapeHtml(x)}</li>`).join('')}
  function escapeHtml(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
  document.querySelectorAll('[data-shop-tab]').forEach(button=>button.addEventListener('click',()=>{shopTab=button.dataset.shopTab;renderShop()}));$('homeBtn').addEventListener('click',enterHome);$('raidGoBtn').addEventListener('click',()=>{if(state.raid.active&&!state.travel)beginTravel(state.raid.key)});$('shopJumpBtn').addEventListener('click',()=>$('shopDialog').showModal());$('interruptBtn').addEventListener('click',()=>{cancelOccupation();render();save()});$('helpBtn').addEventListener('click',()=>$('helpDialog').showModal());document.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',()=>b.closest('dialog').close()));
  $('renameBtn').addEventListener('click',()=>{$('nameInput').value=state.name||'';$('nameDialog').showModal()});$('nameDialog').querySelector('form').addEventListener('submit',e=>{const name=$('nameInput').value.trim().slice(0,12);if(!name){e.preventDefault();$('nameInput').focus();return}state.name=name;state.nameChosen=true;log(`${name}として冒険者登録した。`);render();save()});
