  state.lastTick=state.lastTick||Date.now();document.addEventListener('pointerdown',()=>noteActivity());document.addEventListener('keydown',()=>noteActivity());document.addEventListener('wheel',()=>noteActivity(),{passive:true});document.addEventListener('visibilitychange',()=>{const now=Date.now();settlePoints(now);if(document.visibilityState==='visible')state.lastInteractionAt=now;state.lastWasVisible=document.visibilityState==='visible';save();render()});if(!state.raid.active)updateRaid(Date.now());render();clock();if(!state.nameChosen||!state.name)$('nameDialog').showModal();setInterval(()=>{tick();clock()},1000);
